P = [
 dict(pmid='', doi='10.21203/rs.3.rs-11640660/v1', journal='Research Square', title='Assessment of Particulate Matter Emissions from Corn-Milling Sites in Cape Coast Metropolitan, Southern Ghana', tier='B', basis='Low-cost sensor / network', short='Cape Coast milling markets, 10 months of IQAir optical PM: PM2.5 27-29 ug/m3, WHO 24-h exceeded on 61-92% of days (preprint)', design='Long-term field measurement campaign', pm='IQAir AirVisual Outdoor optical monitors at 1.5 m, 5-minute PM1, PM2.5, PM10, March-December 2024', geo='Ghana (Cape Coast)', endpoint='Concentrations, guideline exceedance and EPA-method hazard quotients at grain and spice milling markets', affil='University of Cape Coast, Ghana; University of Cape Coast, Ghana', n='Research Square preprint, not peer reviewed. Ten-month deployment (March-December 2024) of IQAir AirVisual Outdoor optical monitors at breathing height at two informal milling markets in Cape Coast, 5-minute PM1, PM2.5 and PM10. Mean PM2.5 was 27.0 and 28.9 ug/m3, above the WHO 24-h guideline on 61% and 92% of days; mean PM10 53.5 and 57.5 ug/m3. Peaks tracked grain milling (June-August) and spice milling (December); hazard quotients were 1.80 and 1.93 for PM2.5. Weakness: uncorrected optical sensors in coarse organic dust with no gravimetric or reference co-location reported and humidity not addressed; HQs against ambient guidelines are not occupational limits. Relevance: direct - a long low-cost deployment in an unmonitored African setting that shows the calibration gap for non-urban aerosol types.', sub=corpus.OCC),
 dict(pmid='', doi='10.21203/rs.3.rs-11628121/v1', journal='Research Square', title='Assessment of Particulate Matter Pollution in Mining Communities in Southwestern Ghana', tier='C', basis='Low-cost sensor / network', short='Southwestern Ghana mining community vs background, 6-9 months of IQAir PM: Akoon highest (PM10 to 121 ug/m3); humidity episodes (preprint)', design='Multi-site monitoring campaign', pm='IQAir monitor PM1, PM2.5, PM10 at three sites for 6-9 months', geo='Ghana', endpoint='Spatial and temporal PM variation and meteorological drivers', affil='University of Cape Coast, Ghana; University of Cape Coast, Ghana', n='Research Square preprint, not peer reviewed, from the same Cape Coast group. IQAir monitors recorded PM10, PM2.5 and PM1 for 6-9 months at three southwestern Ghana sites: an artisanal gold-mining community (Akoon), Mile 7 and a background site (Agric Hill). Akoon was highest (PM10 up to 121 ug/m3); humidity above 87% and stable high pressure coincided with episodes, and a November peak occurred despite favourable dispersion. Temperature, humidity and pressure explained 51-62% of variance; high PM1/PM2.5 ratios were read as a fine-particle contribution. Weakness: optical monitors without reported correction, so part of the humidity association is likely hygroscopic-growth artefact; one monitor per site, unequal record lengths. Relevance: above 85% RH uncorrected consumer optical readings inflate, so the meteorological result is confounded by the instrument.', sub=corpus.EXPO),
 dict(pmid='43057454', doi='10.1016/j.envpol.2026.129575', journal='Environmental Pollution', title='Impact of improved biomass stove intervention on PM-bound PAHs: concentration, size distribution, and health risk', tier='B', basis='Lab / research instrument', short='Xuanwei improved-stove intervention: indoor PM2.5-bound PAHs 31.5 to 21.2 ng/m3 with gasifier stoves; BaP-eq and ILCR down ~32.5%', design='Intervention field trial (non-randomised)', pm='Size-resolved indoor PM-bound PAHs before and after replacing traditional stoves with three improved types', geo='China (Xuanwei, Yunnan)', endpoint='Indoor PM2.5-bound PAHs, PAH size distribution, BaP-equivalent concentration and incremental lifetime cancer risk', affil='Kunming University of Science and Technology, China; Peking University, China', n='Rural Xuanwei, Yunnan: traditional biomass stoves replaced with three improved types, indoor PM-bound PAHs measured by particle size before and after. PM2.5-bound PAHs fell most with gasifier stoves (31.52 +/- 15.44 to 21.19 +/- 1.91 ng/m3), with stove-fuel-specific shifts in size distribution; BaP-equivalent concentrations and estimated incremental lifetime cancer risk fell 32.5% with gasifiers. Weakness: before-after design without concurrent controls, so season and fuel are confounded; household numbers and sampling durations are not in the abstract; ILCR rests on default exposure factors. Relevance: PAH reductions are invisible to mass sensors; stove trials should pair optical PM with a composition or black-carbon proxy.', sub=corpus.OCC),
 dict(pmid='43057446', doi='10.1016/j.envpol.2026.129585', journal='Environmental Pollution', title='Organic molecular markers for offline atmospheric particulate matter source apportionment: A comprehensive review', tier='B', basis='Review / no primary exposure', short='Review of 142 studies: organic molecular markers sharpen offline PM source apportionment; diagnostic ratios undermined by inconsistent reference ranges', design='Critical review', pm='Organic molecular markers and diagnostic ratios in filter-based PM; PMF and other receptor models', geo='Global / multi-region', endpoint='Performance and gaps of organic-marker source apportionment', affil="Universite du Littoral Cote d'Opale, France; Universite du Littoral Cote d'Opale, France", n='Review of 142 studies on organic molecular markers (OMM) in offline PM source apportionment, covering diagnostic markers and ratios and receptor models that include organic compounds. Adding OMM improves source resolution and separation of overlapping sources relative to inorganic-only inputs; PMF is the dominant model. Diagnostic ratios remain useful for quick combustion attribution but suffer from inconsistent reference ranges and neglect of atmospheric transformation of the marker compounds. Gaps: incomplete OM characterisation and limited, non-harmonised marker sets. Weakness: no stated search protocol and no quantitative comparison of apportionment performance in the abstract. Relevance: sensor networks infer sources only through covariance with gases; OMM-resolved filter campaigns are the ground truth against which those sensor-based source signatures should be tested.', sub=corpus.EXPO),
]
